import{_ as s,o as a,c as i,a2 as o}from"./chunks/framework.CuUVYbLV.js";const b=JSON.parse('{"title":"01 安装并跑通第一个角色","description":"教程第 01 章：安装 rolebox、用 rolebox init 创建 code-reviewer，并让 harness 加载它。","frontmatter":{"title":"01 安装并跑通第一个角色","description":"教程第 01 章：安装 rolebox、用 rolebox init 创建 code-reviewer，并让 harness 加载它。"},"headers":[],"relativePath":"02-Guide/tutorial/01-install.md","filePath":"02-Guide/tutorial/01-install.md"}'),l={name:"02-Guide/tutorial/01-install.md"};function n(t,e,d,p,c,r){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="_01-安装并跑通第一个角色-install-and-run" tabindex="-1">01 安装并跑通第一个角色（Install and Run） <a class="header-anchor" href="#_01-安装并跑通第一个角色-install-and-run" aria-label="Permalink to &quot;01 安装并跑通第一个角色（Install and Run）&quot;">​</a></h1><p>本章把 rolebox 装进你的 harness，并让第一个角色 <code>code-reviewer</code> 跑起来。走完你会得到一条可以重复执行的最小链路：装插件 → 建角色 → 在 harness 里对话。</p><blockquote><p>前置：无，本教程从零开始｜下一章：<a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">02 让角色懂你的项目</a>｜安装矩阵：<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a></p></blockquote><h2 id="本章造什么" tabindex="-1">本章造什么 <a class="header-anchor" href="#本章造什么" aria-label="Permalink to &quot;本章造什么&quot;">​</a></h2><p>整条教程结束时，你会有一个能评审代码的团队：父角色 <code>code-reviewer</code> 带一个技能、一份引用文档和一个自定义函数，另有 <code>coder</code>、<code>reviewer</code>、<code>doc-writer</code> 三个子代理，最后由图引擎串成流水线。这一章只造第一块：一个能对话的角色。</p><p><strong>角色（role，用 <code>role.yaml</code> 声明、由 harness 在启动时加载的代理定义）</strong> 是 rolebox 的基本单位。本教程用 opencode 作主线，pi 与 dsh 的差别只在安装命令与目录，见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>。</p><h2 id="第-1-步-安装-rolebox" tabindex="-1">第 1 步：安装 rolebox <a class="header-anchor" href="#第-1-步-安装-rolebox" aria-label="Permalink to &quot;第 1 步：安装 rolebox&quot;">​</a></h2><p>rolebox 是一个 <strong>agent harness 插件（plugin，装进 harness 配置目录、由 harness 启动时加载的扩展包）</strong>。opencode 的安装命令是在它的配置目录里 <code>npm install rolebox</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/opencode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rolebox</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，包数量与耗时随 npm 版本、网络环境略有差异）：</span></span>
<span class="line"><span>added 83 packages in 22s</span></span></code></pre></div><p>另外两个 harness 各一行：</p><ul><li>pi：<code>pi install npm:rolebox</code>（想在项目里安装用 <code>pi install -l npm:rolebox</code>）</li><li>dsh：<code>dsh plugin --profile &lt;name&gt; add rolebox</code></li></ul><p>opencode 还必须在配置里声明插件，否则它不会被加载：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ~/.config/opencode/opencode.jsonc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rolebox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><h2 id="第-2-步-创建-code-reviewer" tabindex="-1">第 2 步：创建 code-reviewer <a class="header-anchor" href="#第-2-步-创建-code-reviewer" aria-label="Permalink to &quot;第 2 步：创建 code-reviewer&quot;">​</a></h2><p>角色目录决定 harness 去哪里找角色：<code>&lt;会话工作目录&gt;/rolebox/</code> 存在时优先，否则用 harness 的全局角色目录（opencode 是 <code>~/.config/opencode/rolebox</code>）。本教程把角色放进练习项目 <code>~/rolebox-lab</code>，随项目走，也不污染全局配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab/rolebox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab/rolebox</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code-reviewer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到：</span></span>
<span class="line"><span>✓ Created standard role at /Users/&lt;你&gt;/rolebox-lab/rolebox/code-reviewer</span></span>
<span class="line"><span>Run \`rolebox sync opencode\` to deploy</span></span></code></pre></div><p><code>-y</code> 跳过交互向导、使用默认的 <code>standard</code> 模板，角色目录建在当前目录下的 <code>code-reviewer/</code>。</p><p>确认生成了什么：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code-reviewer</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（顺序随 ls 的区域设置略有差异）：</span></span>
<span class="line"><span>functions  PROMPT.md  role.yaml  skills</span></span></code></pre></div><ul><li><code>role.yaml</code> —— 角色配置：名称、描述、提示词文件，以及技能与函数清单。</li><li><code>PROMPT.md</code> —— 系统提示词，角色的「人格」与工作约定；后面每一章都会改它。</li><li><code>skills/</code> —— 技能（skill，按需加载、命中场景才注入上下文的知识模块）目录，模板只放了一个 <code>README.md</code> 占位。</li><li><code>functions/</code> —— 函数（function，改变角色行为方式的指令单元）目录，同样是 <code>README.md</code> 占位。</li></ul><p><code>standard</code> 模板只生成这四样，<strong>没有</strong> <code>references/</code> 目录；<a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">02 让角色懂你的项目</a>会按需创建它。</p><h2 id="第-3-步-让-harness-加载它" tabindex="-1">第 3 步：让 harness 加载它 <a class="header-anchor" href="#第-3-步-让-harness-加载它" aria-label="Permalink to &quot;第 3 步：让 harness 加载它&quot;">​</a></h2><p>角色已经在会话工作目录下的 <code>rolebox/</code> 里，所以从练习项目根目录启动 harness 即可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/rolebox-lab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，随 harness 与版本不同略有差异）：</span></span>
<span class="line"><span>代理列表里出现 code-reviewer</span></span></code></pre></div><p>选中 <code>code-reviewer</code> 开始会话。如果你更希望角色对所有项目生效，把同样的 <code>rolebox init</code> 放进全局角色目录（opencode 是 <code>~/.config/opencode/rolebox</code>，pi 与 dsh 见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>）即可；两处同名时，会话工作目录下的优先。</p><h2 id="第-4-步-问它一个问题" tabindex="-1">第 4 步：问它一个问题 <a class="header-anchor" href="#第-4-步-问它一个问题" aria-label="Permalink to &quot;第 4 步：问它一个问题&quot;">​</a></h2><p>在会话里问它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个仓库的编码规范是什么？</span></span></code></pre></div><p>它会用 <code>PROMPT.md</code> 的语气回答，但答不出你的规范——因为 <code>PROMPT.md</code> 现在还是模板里的 <code>TODO</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例输出（随模型与 harness 不同会有差异）：</span></span>
<span class="line"><span>code-reviewer：我还没有拿到这个仓库的编码规范，role.yaml 里也没有相关约定……</span></span></code></pre></div><p>记住这一刻——这正是下一章要修的东西。</p><h2 id="rolebox-sync-与-rolebox-list-管什么" tabindex="-1">rolebox sync 与 rolebox list 管什么 <a class="header-anchor" href="#rolebox-sync-与-rolebox-list-管什么" aria-label="Permalink to &quot;rolebox sync 与 rolebox list 管什么&quot;">​</a></h2><p>这两个子命令面向<strong>从注册中心安装的角色</strong>，而不是你 <code>init</code> 出来的本地角色：<code>rolebox install &lt;角色名&gt;</code> 下载角色并登记到安装锁文件，<code>rolebox sync &lt;harness&gt;</code> 把锁文件里的条目部署到该 harness 的角色目录，<code>rolebox list</code> 列出锁文件内容。本地角色不经过锁文件，放进角色目录就已经生效，所以这两条命令现在给出的是空结果——这是正常的，不是出错：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rolebox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencode</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（还没有安装过注册中心角色时）：</span></span>
<span class="line"><span>No roles installed. Run \`rolebox install &lt;role&gt;\` to get started.</span></span>
<span class="line"><span>Synced 0 roles to opencode</span></span></code></pre></div><p>想让锁文件里有内容，用 <code>rolebox install &lt;角色名&gt;</code> 装一个注册中心角色，见<a href="/rolebox-docs/03-Reference/registry.html">注册中心</a>与<a href="/rolebox-docs/03-Reference/cli.html">CLI 参考</a>。</p><h2 id="你现在拥有什么" tabindex="-1">你现在拥有什么 <a class="header-anchor" href="#你现在拥有什么" aria-label="Permalink to &quot;你现在拥有什么&quot;">​</a></h2><ul><li>一个装好 rolebox 插件的 harness；</li><li><code>~/rolebox-lab/rolebox/code-reviewer/</code>，里面有 <code>role.yaml</code>、<code>PROMPT.md</code>、<code>skills/</code>、<code>functions/</code>；</li><li>harness 里可以选择 <code>code-reviewer</code> 并对话；</li><li><code>rolebox install</code> / <code>sync</code> / <code>list</code> 各自负责什么。</li></ul><p>下一章 <a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">02 让角色懂你的项目</a>：把项目约定写进 <code>PROMPT.md</code>，再加一个按需加载的技能。</p>`,43)])])}const k=s(l,[["render",n]]);export{b as __pageData,k as default};
